SELECT COUNT(*) AS cnt
FROM order_payments
WHERE payment_type = 'credit_card';

SELECT COUNT(*) AS product_cnt
FROM products
WHERE product_weight_g > 5000;

SELECT COUNT(*) AS undelivered_orders_count
FROM orders
WHERE order_delivered_customer_date IS NULL;

SELECT COUNT(*) AS item_count
FROM order_items
WHERE price < 10;

SELECT COUNT(*) AS urgent_ticket_count
FROM support_tickets
WHERE priority = '4';

SELECT COUNT(*) AS low_stock_records
FROM inventory
WHERE quantity < safety_stock;

SELECT SUM(refund_amount) AS total_refund_amount
FROM refunds
WHERE status = 4;

SELECT COUNT(*) AS late_order_count
FROM orders
WHERE order_delivered_customer_date > order_estimated_delivery_date;
